/* navigatorslab-home — Netflix-style NavigatorLabs site.
 * Routes:  /                 -> homepage
 *          /apps/style.css   -> shared stylesheet
 *          /apps/<slug>/     -> dedicated app page (8 apps)
 * Zone routes `navigatorslab.com/` and `navigatorslab.com/apps*` both point
 * here; every other path keeps serving via navigatorslab-tools.
 * Zero JavaScript, zero external fetches — all motion is CSS.
 */
addEventListener("fetch", function (event) { event.respondWith(handle(event.request)); });

var HEADERS_HTML = {
  "content-type": "text/html; charset=utf-8",
  "content-security-policy": "default-src 'none'; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; media-src 'self' blob:; font-src 'self' data:; worker-src 'self' blob:; child-src 'self' blob:; frame-ancestors 'none'; base-uri 'none'; form-action 'none'",
  "x-content-type-options": "nosniff",
  "x-frame-options": "DENY",
  "referrer-policy": "no-referrer",
  "cross-origin-opener-policy": "same-origin",
  "cross-origin-resource-policy": "same-origin",
  "permissions-policy": "camera=(), microphone=(), geolocation=(), payment=(), usb=()",
  "strict-transport-security": "max-age=31536000; includeSubDomains",
  "cache-control": "public, max-age=600"
};
var HEADERS_CSS = {
  "content-type": "text/css; charset=utf-8",
  "cache-control": "public, max-age=3600"
};

var PAGES = {"home": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>NavigatorLabs \u2014 local-first, private-by-default software</title>\n<meta name=\"description\" content=\"Eight free, local-first apps: reimagine-it, integration-rot, PDF Studio, 23 private tools and more. No uploads, no accounts, no telemetry.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n\n<header class=\"nav\" id=\"nav\">\n  <a class=\"brand\" href=\"/\">NavigatorLabs<small>local-first software</small></a>\n  <nav class=\"nav-links\">\n    <a href=\"/\" class=\"on\">Home</a>\n    <a href=\"/apps/reimagine-it/\">Apps</a>\n    <a href=\"/apps/integration-rot/\">Developers</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n  <div class=\"nav-right\"><span class=\"pill\"><b>8</b> apps \u00b7 free \u00b7 local-first</span></div>\n</header>\n\n<section class=\"billboard\">\n\n<div class=\"slide\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\"></div>\n  <div class=\"slide-shade\"></div>\n  <div class=\"slide-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 The lab's flagship</span></div>\n    <h1 class=\"bill-title\">reimagine-it</h1>\n    <div class=\"bill-meta\">\n      <span class=\"maturity\">FLAGSHIP</span><span style=\"color:#a7a7b3;font-size:13px\">v2.15.0 \u00b7 MIT \u00b7 CLI + Web</span>\n    </div>\n    <p class=\"bill-desc\">The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p>\n    <div class=\"bill-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/reimagine/\"><span class=\"tri\">\u25b6</span> Open playground</a>\n      <a class=\"btn btn-more\" href=\"/apps/reimagine-it/\">\u24d8 Details &amp; examples</a>\n    </div>\n  </div>\n</div>\n\n<div class=\"slide\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(115deg,#f59e0b,#ef4444);\"></div>\n  <div class=\"slide-shade\"></div>\n  <div class=\"slide-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 The newest build</span></div>\n    <h1 class=\"bill-title\">integration-rot</h1>\n    <div class=\"bill-meta\">\n      <span class=\"maturity\">NEW</span><span style=\"color:#a7a7b3;font-size:13px\">v0.4.4 \u00b7 131 tests \u00b7 MIT</span>\n    </div>\n    <p class=\"bill-desc\">Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.</p>\n    <div class=\"bill-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/Integrationrot\"><span class=\"tri\">\u25b6</span> Read the docs</a>\n      <a class=\"btn btn-more\" href=\"/apps/integration-rot/\">\u24d8 Details &amp; examples</a>\n    </div>\n  </div>\n</div>\n\n<div class=\"slide\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(150deg,#dc2626,#7c2d12);\"></div>\n  <div class=\"slide-shade\"></div>\n  <div class=\"slide-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 A lab original</span></div>\n    <h1 class=\"bill-title\">PDF Studio</h1>\n    <div class=\"bill-meta\">\n      <span class=\"maturity\">ORIGINAL</span><span style=\"color:#a7a7b3;font-size:13px\">Web app \u00b7 100% client-side \u00b7 MIT</span>\n    </div>\n    <p class=\"bill-desc\">A complete PDF editor that never uploads your file. Edit the text inside your PDF, fill forms, OCR scans, sign, redact and diff revisions \u2014 entirely in your browser.</p>\n    <div class=\"bill-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/pdf-studio/\"><span class=\"tri\">\u25b6</span> Open the editor</a>\n      <a class=\"btn btn-more\" href=\"/apps/pdf-studio/\">\u24d8 Details &amp; examples</a>\n    </div>\n  </div>\n</div>\n</section>\n<section class=\"shelf\">\n  <h2><span class=\"nlab\">NavigatorLabs</span> Originals</h2>\n  <p class=\"sub\">Eight apps. One standard: free, local-first, no telemetry. Each appears once \u2014 pick yours.</p>\n  <div class=\"grid\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/reimagine-it/\" aria-label=\"reimagine-it details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\">\n      <span class=\"card-badge\">FLAGSHIP</span>\n      <span class=\"glyph\">R</span>\n      <span class=\"gname\">reimagine-it</span>\n    </div>\n    <div class=\"card-info\"><h3>reimagine-it</h3><p>The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/reimagine/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/reimagine-it/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/integration-rot/\" aria-label=\"integration-rot details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(115deg,#f59e0b,#ef4444);\">\n      <span class=\"card-badge\">NEW</span>\n      <span class=\"glyph\">I</span>\n      <span class=\"gname\">integration-rot</span>\n    </div>\n    <div class=\"card-info\"><h3>integration-rot</h3><p>Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/Integrationrot\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/integration-rot/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/pdf-studio/\" aria-label=\"PDF Studio details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(150deg,#dc2626,#7c2d12);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">P</span>\n      <span class=\"gname\">PDF Studio</span>\n    </div>\n    <div class=\"card-info\"><h3>PDF Studio</h3><p>A complete PDF editor that never uploads your file. Edit the text inside your PDF, fill forms, OCR scans, sign, redact and diff revisions \u2014 entirely in your browser.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/pdf-studio/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/pdf-studio/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/tools/\" aria-label=\"23 Tools details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(125deg,#0d9488,#0ea5e9);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">T</span>\n      <span class=\"gname\">23 Tools</span>\n    </div>\n    <div class=\"card-info\"><h3>23 Tools</h3><p>Twenty-three tools, games and projects for everyday files. Strip photo GPS, shrink images, OCR receipts to CSV, diff contracts word by word \u2014 nothing leaves your device.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/tools/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/tools/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/book-guide-mcp/\" aria-label=\"book-guide-mcp details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(140deg,#059669,#a3e635);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">B</span>\n      <span class=\"gname\">book-guide-mcp</span>\n    </div>\n    <div class=\"card-info\"><h3>book-guide-mcp</h3><p>Turn the books you trust into skills your coding agent can call. Playbooks, frameworks and Socratic tutors \u2014 every claim cited with a locator, everything running locally.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/book-guide-mcp\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/book-guide-mcp/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/design-health-action/\" aria-label=\"design-health-action details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(120deg,#0284c7,#6366f1);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">D</span>\n      <span class=\"gname\">design-health-action</span>\n    </div>\n    <div class=\"card-info\"><h3>design-health-action</h3><p>Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/design-health-action\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/design-health-action/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/liecatchers/\" aria-label=\"liecatchers details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(155deg,#3f3f46,#b91c1c);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">L</span>\n      <span class=\"gname\">liecatchers</span>\n    </div>\n    <div class=\"card-info\"><h3>liecatchers</h3><p>Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/liecatchers\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/liecatchers/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/data-insights/\" aria-label=\"Data Insights details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(130deg,#4f46e5,#0ea5e9);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">\u0394</span>\n      <span class=\"gname\">Data Insights</span>\n    </div>\n    <div class=\"card-info\"><h3>Data Insights</h3><p>A founder intelligence platform that reads the public web for you. Daily 5W1H briefs and weekly synthesis from technology, startup, research and security signals \u2014 with agent APIs on top.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/data-insights\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/data-insights/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "reimagine-it": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>reimagine-it \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 The lab's flagship</span></div>\n    <h1 class=\"d-title\">reimagine-it</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>ver</b> \u00b7 v2.15.0</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>plat</b> \u00b7 CLI + Web</span></div>\n    <p class=\"d-log\">The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/reimagine/\"><span class=\"tri\">\u25b6</span> Open playground</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/reimagine-it\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things reimagine-it does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>Six government pages, seventeen directions</h3><p>NPS, NASA, NOAA, Census, Federal Register and Smithsonian pages were each regenerated in 17 design directions \u2014 byte-identically reproducible in CI.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>The 19-rule deterministic audit</h3><p>Every output is scored against 19 design rules with no model in the loop. This very site scored 19/19 CLEAN.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>Live playground, no install</h3><p>Paste any HTML into the playground, pick a direction, and take home a standalone redesigned page.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>An agent skill, not just a CLI</h3><p>Ships with a Claude Code / Cursor skill and an MCP server, so coding agents can drive redesigns themselves.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>17 content-derived design directions</li>\n<li>19-rule deterministic audit (no LLM)</li>\n<li>MCP server + agent skill for Claude Code and Cursor</li>\n<li>Byte-identical regeneration across 168-file corpus in CI</li>\n<li>Zero runtime dependencies, offline, MIT-licensed</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/integration-rot/\" aria-label=\"integration-rot details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(115deg,#f59e0b,#ef4444);\">\n      <span class=\"card-badge\">NEW</span>\n      <span class=\"glyph\">I</span>\n      <span class=\"gname\">integration-rot</span>\n    </div>\n    <div class=\"card-info\"><h3>integration-rot</h3><p>Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/Integrationrot\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/integration-rot/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/design-health-action/\" aria-label=\"design-health-action details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(120deg,#0284c7,#6366f1);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">D</span>\n      <span class=\"gname\">design-health-action</span>\n    </div>\n    <div class=\"card-info\"><h3>design-health-action</h3><p>Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/design-health-action\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/design-health-action/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/liecatchers/\" aria-label=\"liecatchers details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(155deg,#3f3f46,#b91c1c);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">L</span>\n      <span class=\"gname\">liecatchers</span>\n    </div>\n    <div class=\"card-info\"><h3>liecatchers</h3><p>Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/liecatchers\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/liecatchers/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "integration-rot": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>integration-rot \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(115deg,#f59e0b,#ef4444);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 The newest build</span></div>\n    <h1 class=\"d-title\">integration-rot</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>ver</b> \u00b7 v0.4.4</span>\n<span class=\"m\"><b>star</b> \u00b7 131 tests</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>plat</b> \u00b7 CLI + REST + MCP</span></div>\n    <p class=\"d-log\">Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/Integrationrot\"><span class=\"tri\">\u25b6</span> Read the docs</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/integration-rot\">GitHub \u2197</a>\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/Integrationrot#waitlist\"><span class=\"tri\">\u2726</span> Join the waitlist</a>\n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things integration-rot does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>Stripe Charges becomes PaymentIntents</h3><p>The scanner finds client.charges.create calls, the fixer drafts the PaymentIntents rewrite, and contract tests prove it before the fix is kept.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>SendGrid v2 mail.send, retired</h3><p>The v2 JSON endpoint pattern is detected and rewritten for the v3 API \u2014 including the endpoint URL itself.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>Proof, not promises</h3><p>Each fix is applied to a temp copy and exercised by generated contract tests. Green keeps it; red reverts it, automatically.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>The hosted waitlist</h3><p>A managed version is coming \u2014 monitoring, PRs and all. Join the waitlist from the docs page.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>Deprecation DB covering 76 SDK packages</li>\n<li>Deterministic planner: scan, draft, test, keep-or-revert</li>\n<li>Contract tests generated per fix, run hermetically</li>\n<li>CLI, REST API and MCP server interfaces</li>\n<li>Zero runtime dependencies</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/liecatchers/\" aria-label=\"liecatchers details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(155deg,#3f3f46,#b91c1c);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">L</span>\n      <span class=\"gname\">liecatchers</span>\n    </div>\n    <div class=\"card-info\"><h3>liecatchers</h3><p>Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/liecatchers\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/liecatchers/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/design-health-action/\" aria-label=\"design-health-action details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(120deg,#0284c7,#6366f1);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">D</span>\n      <span class=\"gname\">design-health-action</span>\n    </div>\n    <div class=\"card-info\"><h3>design-health-action</h3><p>Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/design-health-action\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/design-health-action/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/reimagine-it/\" aria-label=\"reimagine-it details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\">\n      <span class=\"card-badge\">FLAGSHIP</span>\n      <span class=\"glyph\">R</span>\n      <span class=\"gname\">reimagine-it</span>\n    </div>\n    <div class=\"card-info\"><h3>reimagine-it</h3><p>The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/reimagine/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/reimagine-it/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "pdf-studio": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>PDF Studio \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"A complete PDF editor that never uploads your file. Edit the text inside your PDF, fill forms, OCR scans, sign, redact and diff revisions \u2014 entirely in your browser.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(150deg,#dc2626,#7c2d12);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 A lab original</span></div>\n    <h1 class=\"d-title\">PDF Studio</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>plat</b> \u00b7 Web app</span>\n<span class=\"m\"><b>star</b> \u00b7 100% client-side</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>ver</b> \u00b7 No account</span></div>\n    <p class=\"d-log\">A complete PDF editor that never uploads your file. Edit the text inside your PDF, fill forms, OCR scans, sign, redact and diff revisions \u2014 entirely in your browser.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/pdf-studio/\"><span class=\"tri\">\u25b6</span> Open the editor</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/NavigatorsLab-PDF-Studio\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things PDF Studio does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>Redact a contract</h3><p>Burn social security and bank numbers out of a PDF so they can never be recovered.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>Fill and sign a W-9</h3><p>Complete form fields and add your signature without printing a page.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>OCR a phone scan</h3><p>Turn a crooked photo of a document into searchable, selectable text.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>Diff two revisions</h3><p>Compare proposal v2 against v3 and see exactly what changed.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>Edit PDF text in place</li>\n<li>Form filling + e-signature</li>\n<li>On-device OCR for scans</li>\n<li>True redaction (burned, not covered)</li>\n<li>Revision diffing, on-device LLM helpers</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/tools/\" aria-label=\"23 Tools details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(125deg,#0d9488,#0ea5e9);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">T</span>\n      <span class=\"gname\">23 Tools</span>\n    </div>\n    <div class=\"card-info\"><h3>23 Tools</h3><p>Twenty-three tools, games and projects for everyday files. Strip photo GPS, shrink images, OCR receipts to CSV, diff contracts word by word \u2014 nothing leaves your device.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/tools/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/tools/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/reimagine-it/\" aria-label=\"reimagine-it details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\">\n      <span class=\"card-badge\">FLAGSHIP</span>\n      <span class=\"glyph\">R</span>\n      <span class=\"gname\">reimagine-it</span>\n    </div>\n    <div class=\"card-info\"><h3>reimagine-it</h3><p>The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/reimagine/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/reimagine-it/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/data-insights/\" aria-label=\"Data Insights details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(130deg,#4f46e5,#0ea5e9);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">\u0394</span>\n      <span class=\"gname\">Data Insights</span>\n    </div>\n    <div class=\"card-info\"><h3>Data Insights</h3><p>A founder intelligence platform that reads the public web for you. Daily 5W1H briefs and weekly synthesis from technology, startup, research and security signals \u2014 with agent APIs on top.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/data-insights\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/data-insights/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "tools": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>23 Tools \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"Twenty-three tools, games and projects for everyday files. Strip photo GPS, shrink images, OCR receipts to CSV, diff contracts word by word \u2014 nothing leaves your device.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(125deg,#0d9488,#0ea5e9);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 Twenty-three deep</span></div>\n    <h1 class=\"d-title\">23 Tools</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>ver</b> \u00b7 23 tools, games & projects</span>\n<span class=\"m\"><b>star</b> \u00b7 100% client-side</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>plat</b> \u00b7 MCP endpoint</span></div>\n    <p class=\"d-log\">Twenty-three tools, games and projects for everyday files. Strip photo GPS, shrink images, OCR receipts to CSV, diff contracts word by word \u2014 nothing leaves your device.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://navigatorslab.com/tools/\"><span class=\"tri\">\u25b6</span> Browse the tools</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/NavigatorsLab-Tools\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things 23 Tools does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>Strip GPS before sharing</h3><p>Remove location data from vacation photos before they go anywhere.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>Receipt photo becomes a spreadsheet</h3><p>Snap a receipt; get clean CSV rows for expenses.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>Contract diff, word by word</h3><p>Redline two drafts and catch the one changed clause that matters.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>Shrink a folder for the web</h3><p>Batch images down to size with no uploads and no quality surprises.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>Documents, text, data, images, media and files \u2014 plus games</li>\n<li>Deep links with parameters drive any tool from a URL</li>\n<li>MCP endpoint so AI agents can operate every tool</li>\n<li>QR code for every tool \u2014 phone handoff in one scan</li>\n<li>Fully offline once loaded; zero telemetry</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/pdf-studio/\" aria-label=\"PDF Studio details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(150deg,#dc2626,#7c2d12);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">P</span>\n      <span class=\"gname\">PDF Studio</span>\n    </div>\n    <div class=\"card-info\"><h3>PDF Studio</h3><p>A complete PDF editor that never uploads your file. Edit the text inside your PDF, fill forms, OCR scans, sign, redact and diff revisions \u2014 entirely in your browser.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/pdf-studio/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/pdf-studio/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/book-guide-mcp/\" aria-label=\"book-guide-mcp details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(140deg,#059669,#a3e635);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">B</span>\n      <span class=\"gname\">book-guide-mcp</span>\n    </div>\n    <div class=\"card-info\"><h3>book-guide-mcp</h3><p>Turn the books you trust into skills your coding agent can call. Playbooks, frameworks and Socratic tutors \u2014 every claim cited with a locator, everything running locally.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/book-guide-mcp\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/book-guide-mcp/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/reimagine-it/\" aria-label=\"reimagine-it details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\">\n      <span class=\"card-badge\">FLAGSHIP</span>\n      <span class=\"glyph\">R</span>\n      <span class=\"gname\">reimagine-it</span>\n    </div>\n    <div class=\"card-info\"><h3>reimagine-it</h3><p>The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/reimagine/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/reimagine-it/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "book-guide-mcp": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>book-guide-mcp \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"Turn the books you trust into skills your coding agent can call. Playbooks, frameworks and Socratic tutors \u2014 every claim cited with a locator, everything running locally.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(140deg,#059669,#a3e635);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 Agents, meet your library</span></div>\n    <h1 class=\"d-title\">book-guide-mcp</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>ver</b> \u00b7 v0.2.0</span>\n<span class=\"m\"><b>plat</b> \u00b7 MCP server</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>star</b> \u00b7 No API keys</span></div>\n    <p class=\"d-log\">Turn the books you trust into skills your coding agent can call. Playbooks, frameworks and Socratic tutors \u2014 every claim cited with a locator, everything running locally.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://github.com/Kayforkind/book-guide-mcp\"><span class=\"tri\">\u25b6</span> View on GitHub</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/book-guide-mcp\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things book-guide-mcp does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>skill_match routes the question</h3><p>Ask how to price a launch; the server routes it to the pricing book's skill, not generic advice.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>skill_cite with locators</h3><p>Every claim the agent makes carries a book locator you can verify.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>The Socratic tutor</h3><p>Learns by questioning \u2014 the agent teaches you instead of telling you.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>The Avicenna tutor</h3><p>Teaches from first principles, step by step, from texts you own.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>L0 Library to L4 Mentor skill packages</li>\n<li>skill_match, skill_search and skill_cite tools</li>\n<li>Socratic and Avicenna mentor modes</li>\n<li>MCP hosts include Cursor, Claude Code, VS Code and Zed</li>\n<li>Local-first; no API keys for the core loop</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/liecatchers/\" aria-label=\"liecatchers details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(155deg,#3f3f46,#b91c1c);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">L</span>\n      <span class=\"gname\">liecatchers</span>\n    </div>\n    <div class=\"card-info\"><h3>liecatchers</h3><p>Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/liecatchers\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/liecatchers/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/tools/\" aria-label=\"23 Tools details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(125deg,#0d9488,#0ea5e9);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">T</span>\n      <span class=\"gname\">23 Tools</span>\n    </div>\n    <div class=\"card-info\"><h3>23 Tools</h3><p>Twenty-three tools, games and projects for everyday files. Strip photo GPS, shrink images, OCR receipts to CSV, diff contracts word by word \u2014 nothing leaves your device.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/tools/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/tools/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/design-health-action/\" aria-label=\"design-health-action details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(120deg,#0284c7,#6366f1);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">D</span>\n      <span class=\"gname\">design-health-action</span>\n    </div>\n    <div class=\"card-info\"><h3>design-health-action</h3><p>Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/design-health-action\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/design-health-action/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "design-health-action": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>design-health-action \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(120deg,#0284c7,#6366f1);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 The CI gate</span></div>\n    <h1 class=\"d-title\">design-health-action</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>ver</b> \u00b7 v1.0.1</span>\n<span class=\"m\"><b>star</b> \u00b7 18 checks</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>plat</b> \u00b7 GitHub Action</span></div>\n    <p class=\"d-log\">Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://github.com/Kayforkind/design-health-action\"><span class=\"tri\">\u25b6</span> View on GitHub</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/design-health-action\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things design-health-action does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>Off-palette accent fails the build</h3><p>More than five non-neutral colors, or an accent outside the palette \u2014 blocked.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>Motion support is mandatory</h3><p>Missing prefers-reduced-motion or focus-visible styles get flagged before merge.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>Fabricated content caught</h3><p>Placeholder labels and invented copy are detected as content failures.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>verdict: CLEAN</h3><p>Each run posts a summary table \u2014 verdict, failures, warnings \u2014 to the workflow.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>18 checks across Typography, Palette, Motion, Content, Structure, Performance</li>\n<li>Deterministic: no model, no network, no API key</li>\n<li>verdict / failures / warnings / summary outputs</li>\n<li>fail-on-warnings and strict modes for tight gates</li>\n<li>The CI-quality-gate half of reimagine-it</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/reimagine-it/\" aria-label=\"reimagine-it details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(135deg,#7c3aed,#db2777);\">\n      <span class=\"card-badge\">FLAGSHIP</span>\n      <span class=\"glyph\">R</span>\n      <span class=\"gname\">reimagine-it</span>\n    </div>\n    <div class=\"card-info\"><h3>reimagine-it</h3><p>The design engine that refuses to invent facts. Point it at any HTML page and it rebuilds the design from the page's own nouns, dates, numbers and colors \u2014 seventeen directions, zero dependencies, fully offline.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/reimagine/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/reimagine-it/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/liecatchers/\" aria-label=\"liecatchers details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(155deg,#3f3f46,#b91c1c);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">L</span>\n      <span class=\"gname\">liecatchers</span>\n    </div>\n    <div class=\"card-info\"><h3>liecatchers</h3><p>Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/liecatchers\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/liecatchers/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/integration-rot/\" aria-label=\"integration-rot details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(115deg,#f59e0b,#ef4444);\">\n      <span class=\"card-badge\">NEW</span>\n      <span class=\"glyph\">I</span>\n      <span class=\"gname\">integration-rot</span>\n    </div>\n    <div class=\"card-info\"><h3>integration-rot</h3><p>Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/Integrationrot\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/integration-rot/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "liecatchers": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>liecatchers \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(155deg,#3f3f46,#b91c1c);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 Trust, verified</span></div>\n    <h1 class=\"d-title\">liecatchers</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>plat</b> \u00b7 CLI</span>\n<span class=\"m\"><b>star</b> \u00b7 10 sensors</span>\n<span class=\"m\"><b>lic</b> \u00b7 MIT</span>\n<span class=\"m\"><b>ver</b> \u00b7 Windows-first</span></div>\n    <p class=\"d-log\">Your agent said \u201cdone.\u201d Prove it. Ten sensors interrogate the workspace after every agent run \u2014 and hand you a signed RECEIPT.json you can paste straight into the next turn.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://github.com/Kayforkind/liecatchers\"><span class=\"tri\">\u25b6</span> View on GitHub</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/liecatchers\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things liecatchers does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>The tests never ran</h3><p>The agent printed \u201cDone\u201d; the sensor shows no test process ever executed. Exit code 1.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>Invented paths in the PR</h3><p>The PR references files that are not in the git diff \u2014 caught and listed.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>Green npm, missing binaries</h3><p>Install looks fine but native modules are absent. The sensor knows.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>RECEIPT.json</h3><p>One signed machine-readable receipt: paste it into the next agent turn and continue honestly.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>10 sensors: commands, git diff, lockfiles, native modules, handoffs</li>\n<li>Signed RECEIPT.json \u2014 the one source of truth</li>\n<li>30-second fail-demo proves the detection works</li>\n<li>Cursor stop-hook runs it automatically</li>\n<li>Zero API keys, Windows-first</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/integration-rot/\" aria-label=\"integration-rot details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(115deg,#f59e0b,#ef4444);\">\n      <span class=\"card-badge\">NEW</span>\n      <span class=\"glyph\">I</span>\n      <span class=\"gname\">integration-rot</span>\n    </div>\n    <div class=\"card-info\"><h3>integration-rot</h3><p>Dependencies rot silently. This autopilot watches yours: it finds every use of a dying API, drafts the migration, and proves the fix with generated contract tests before anything is kept.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/Integrationrot\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/integration-rot/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/book-guide-mcp/\" aria-label=\"book-guide-mcp details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(140deg,#059669,#a3e635);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">B</span>\n      <span class=\"gname\">book-guide-mcp</span>\n    </div>\n    <div class=\"card-info\"><h3>book-guide-mcp</h3><p>Turn the books you trust into skills your coding agent can call. Playbooks, frameworks and Socratic tutors \u2014 every claim cited with a locator, everything running locally.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/book-guide-mcp\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/book-guide-mcp/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/design-health-action/\" aria-label=\"design-health-action details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(120deg,#0284c7,#6366f1);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">D</span>\n      <span class=\"gname\">design-health-action</span>\n    </div>\n    <div class=\"card-info\"><h3>design-health-action</h3><p>Eighteen deterministic design-quality checks as a GitHub Action. It fails your build when the palette drifts, motion support is missing, or content is fabricated \u2014 no LLM, no API key, seconds per run.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/design-health-action\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/design-health-action/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>", "data-insights": "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Data Insights \u2014 NavigatorLabs</title>\n<meta name=\"description\" content=\"A founder intelligence platform that reads the public web for you. Daily 5W1H briefs and weekly synthesis from technology, startup, research and security signals \u2014 with agent APIs on top.\">\n<link rel=\"stylesheet\" href=\"/apps/style.css\">\n</head>\n<body>\n<div class=\"backbar\"><a class=\"back\" href=\"/\">\u2039 All apps</a></div>\n<section class=\"d-hero\">\n  <div class=\"slide-art\" style=\"background:linear-gradient(130deg,#4f46e5,#0ea5e9);\"></div>\n  <div class=\"d-shade\"></div>\n  <div class=\"d-body\">\n    <div class=\"kicker\"><span class=\"n\">N</span><span class=\"tag\">Labs original \u00b7 The morning brief</span></div>\n    <h1 class=\"d-title\">Data Insights</h1>\n    <div class=\"d-meta\"><span class=\"m\"><b>plat</b> \u00b7 Web + CLI</span>\n<span class=\"m\"><b>star</b> \u00b7 Daily briefs</span>\n<span class=\"m\"><b>ver</b> \u00b7 JSON APIs</span></div>\n    <p class=\"d-log\">A founder intelligence platform that reads the public web for you. Daily 5W1H briefs and weekly synthesis from technology, startup, research and security signals \u2014 with agent APIs on top.</p>\n    <div class=\"d-btns\">\n      <a class=\"btn btn-play\" href=\"https://github.com/Kayforkind/data-insights\"><span class=\"tri\">\u25b6</span> View on GitHub</a>\n      <a class=\"btn btn-more\" href=\"https://github.com/Kayforkind/data-insights\">GitHub \u2197</a>\n      \n    </div>\n  </div>\n</section>\n<section class=\"d-sec\">\n  <h2>Examples</h2><p class=\"sub\">Real things Data Insights does \u2014 drawn from the docs, the demos and the repos.</p>\n  <div class=\"ex-grid\"><div class=\"ex\"><div class=\"k\">EXAMPLE 1</div><h3>The daily 5W1H</h3><p>Every morning: who, what, when, where, why and how across the signals that matter.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 2</div><h3>The weekly synthesis</h3><p>Themes, momentum, opportunities, risks and experiments \u2014 plus a print-ready edition.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 3</div><h3>Search any topic</h3><p>npm run cli -- search robotics \u2014 follow a topic into its live signals and source history.</p></div>\n<div class=\"ex\"><div class=\"k\">EXAMPLE 4</div><h3>The agent CLI</h3><p>npm run cli -- search robotics \u2014 the same intelligence, scriptable.</p></div></div>\n</section>\n<section class=\"d-sec\">\n  <h2>Details</h2><p class=\"sub\">What ships with it.</p>\n  <ul class=\"feat\"><li>/report: daily 5W1H brief</li>\n<li>/weekly: synthesis with themes, risks, experiments</li>\n<li>Topic search across live signals and source history</li>\n<li>/portal: headline river without licensed full text</li>\n<li>JSON APIs + CLI for agents</li></ul>\n</section>\n<section class=\"d-sec\">\n  <h2>More Like This</h2><p class=\"sub\">From the same lab, same guarantees.</p>\n  <div class=\"like-row\">\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/tools/\" aria-label=\"23 Tools details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(125deg,#0d9488,#0ea5e9);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">T</span>\n      <span class=\"gname\">23 Tools</span>\n    </div>\n    <div class=\"card-info\"><h3>23 Tools</h3><p>Twenty-three tools, games and projects for everyday files. Strip photo GPS, shrink images, OCR receipts to CSV, diff contracts word by word \u2014 nothing leaves your device.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/tools/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/tools/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/pdf-studio/\" aria-label=\"PDF Studio details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(150deg,#dc2626,#7c2d12);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">P</span>\n      <span class=\"gname\">PDF Studio</span>\n    </div>\n    <div class=\"card-info\"><h3>PDF Studio</h3><p>A complete PDF editor that never uploads your file. Edit the text inside your PDF, fill forms, OCR scans, sign, redact and diff revisions \u2014 entirely in your browser.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://navigatorslab.com/pdf-studio/\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/pdf-studio/\">\u24d8 Details</a>\n  </div>\n</article>\n\n<article class=\"card\">\n  <a class=\"card-main\" href=\"/apps/book-guide-mcp/\" aria-label=\"book-guide-mcp details\">\n    <div class=\"card-art\" style=\"background:linear-gradient(140deg,#059669,#a3e635);\">\n      <span class=\"card-badge\">ORIGINAL</span>\n      <span class=\"glyph\">B</span>\n      <span class=\"gname\">book-guide-mcp</span>\n    </div>\n    <div class=\"card-info\"><h3>book-guide-mcp</h3><p>Turn the books you trust into skills your coding agent can call. Playbooks, frameworks and Socratic tutors \u2014 every claim cited with a locator, everything running locally.</p></div>\n  </a>\n  <div class=\"card-hover\">\n    <a class=\"mini-btn solid\" href=\"https://github.com/Kayforkind/book-guide-mcp\">\u25b6 Open</a>\n    <a class=\"mini-btn\" href=\"/apps/book-guide-mcp/\">\u24d8 Details</a>\n  </div>\n</article></div>\n</section>\n\n<footer>\n  <div class=\"fbrand\">NAVIGATORLABS</div>\n  <p>A one-person software lab. Every app is free and local-first:\n  it runs on your machine or in your browser \u2014 your files are never uploaded,\n  because there is no server to trust. Most apps are MIT-licensed; each\n  repository carries its own license.</p>\n  <nav>\n    <a href=\"/apps/reimagine-it/\">reimagine-it</a>\n    <a href=\"/apps/integration-rot/\">integration-rot</a>\n    <a href=\"/apps/pdf-studio/\">PDF Studio</a>\n    <a href=\"/apps/tools/\">23 Tools</a>\n    <a href=\"https://github.com/Kayforkind\">GitHub</a>\n  </nav>\n</footer>\n\n</body>\n</html>"};
var CSS = "\n:root{\n  --bg:#0b0b0f; --bg2:#121218; --panel:#17171f; --line:#26262f;\n  --txt:#f5f5f7; --mut:#a7a7b3; --dim:#6d6d7a;\n  --brand:#2dd4bf; --brand-d:#0d9488;\n  --serif:\"Iowan Old Style\",\"Palatino Linotype\",Palatino,Georgia,serif;\n  --sans:-apple-system,BlinkMacSystemFont,\"Segoe UI\",Inter,Roboto,Helvetica,Arial,sans-serif;\n  --cond:\"Arial Narrow\",\"Helvetica Neue Condensed\",Impact,sans-serif;\n}\n*{margin:0;padding:0;box-sizing:border-box}\nhtml{scroll-behavior:smooth}\nbody{background:var(--bg);color:var(--txt);font-family:var(--sans);\n  -webkit-font-smoothing:antialiased;overflow-x:hidden}\na{color:inherit;text-decoration:none}\n::selection{background:var(--brand);color:#04211d}\n\n/* ---------- nav ---------- */\n.nav{position:fixed;top:0;left:0;right:0;z-index:50;display:flex;align-items:center;gap:34px;\n  padding:0 4vw;height:68px;background:linear-gradient(180deg,rgba(5,5,8,.92),rgba(5,5,8,.55) 70%,transparent);\n  transition:background .3s}\n.nav.scrolled{background:rgba(8,8,11,.96)}\n.brand{font-family:var(--cond);font-weight:800;font-size:21px;letter-spacing:5px;color:var(--brand);\n  text-transform:uppercase;white-space:nowrap}\n.brand small{display:block;font-size:8px;letter-spacing:6px;color:var(--dim);font-weight:400}\n.nav-links{display:flex;gap:26px;font-size:14px;color:#d7d7de}\n.nav-links a{opacity:.75;transition:opacity .2s}\n.nav-links a:hover,.nav-links a.on{opacity:1;color:#fff}\n.nav-right{margin-left:auto;display:flex;align-items:center;gap:18px;font-size:13px;color:var(--mut)}\n.pill{border:1px solid var(--line);border-radius:20px;padding:6px 14px;font-size:12px;color:var(--txt)}\n.pill b{color:var(--brand)}\n\n/* ---------- billboard ---------- */\n.billboard{position:relative;height:92vh;min-height:620px;overflow:hidden}\n.slide{position:absolute;inset:0;opacity:0;animation:hero 24s infinite}\n.slide:nth-child(2){animation-delay:8s}\n.slide:nth-child(3){animation-delay:16s}\n@keyframes hero{0%{opacity:0}2.5%{opacity:1}31%{opacity:1}35.5%{opacity:0}100%{opacity:0}}\n.slide-art{position:absolute;inset:0}\n.slide-shade{position:absolute;inset:0;\n  background:linear-gradient(77deg,rgba(6,6,10,.94) 20%,rgba(6,6,10,.55) 45%,rgba(6,6,10,.05) 75%),\n             linear-gradient(0deg,var(--bg) 2%,transparent 30%),\n             linear-gradient(180deg,rgba(6,6,10,.6),transparent 26%)}\n.slide-body{position:absolute;left:4vw;bottom:16vh;max-width:640px;z-index:2}\n.kicker{display:flex;align-items:center;gap:10px;margin-bottom:14px}\n.kicker .n{font-family:var(--cond);font-weight:800;color:var(--brand);font-size:15px;letter-spacing:3px}\n.kicker .tag{font-size:11px;letter-spacing:2.5px;color:var(--mut);text-transform:uppercase}\n.bill-title{font-family:var(--serif);font-weight:700;font-size:clamp(46px,6.5vw,88px);\n  line-height:1.02;letter-spacing:-.5px;margin-bottom:16px;text-wrap:balance}\n.bill-meta{display:flex;align-items:center;gap:12px;margin-bottom:14px;font-size:14px}\n.maturity{border:1px solid var(--dim);color:var(--mut);font-size:11px;padding:3px 9px;border-radius:3px;letter-spacing:1px}\n.bill-desc{color:#d9d9e0;font-size:clamp(15px,1.6vw,18px);line-height:1.55;max-width:56ch;margin-bottom:26px}\n.bill-btns{display:flex;gap:12px;flex-wrap:wrap}\n.btn{display:inline-flex;align-items:center;gap:10px;font-weight:700;font-size:16px;\n  border-radius:6px;padding:12px 28px;transition:transform .15s,background .2s;cursor:pointer;border:0}\n.btn:active{transform:scale(.97)}\n.btn-play{background:#fff;color:#0b0b0f}\n.btn-play:hover{background:rgba(255,255,255,.82)}\n.btn-more{background:rgba(109,109,122,.55);color:#fff}\n.btn-more:hover{background:rgba(109,109,122,.38)}\n.btn .tri{font-size:13px}\n\n.card{position:relative;scroll-snap-align:start;border-radius:8px;overflow:hidden;\n  background:var(--panel);transition:transform .25s ease,box-shadow .25s;cursor:pointer}\n.card:hover{transform:translateY(-6px);z-index:10;box-shadow:0 18px 50px rgba(0,0,0,.65)}\n.card-art{position:relative;aspect-ratio:16/9;overflow:hidden}\n.card-art .glyph{position:absolute;right:6px;bottom:-24px;font-family:var(--serif);font-weight:700;\n  font-size:150px;line-height:1;color:rgba(255,255,255,.16)}\n.card-art .gname{position:absolute;left:14px;bottom:10px;font-family:var(--cond);font-weight:800;\n  font-size:15px;letter-spacing:2.5px;color:rgba(255,255,255,.92);text-transform:uppercase;text-shadow:0 2px 8px rgba(0,0,0,.5)}\n.card-badge{position:absolute;top:10px;left:10px;font-size:10px;font-weight:800;letter-spacing:1.8px;\n  background:rgba(0,0,0,.55);border:1px solid rgba(255,255,255,.25);padding:4px 10px;border-radius:4px;color:#fff}\n.card-info{padding:12px 14px 14px}\n.card-info h3{font-size:15px;margin-bottom:6px}\n.card-info p{font-size:12.5px;color:var(--mut);line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;\n  -webkit-box-orient:vertical;overflow:hidden}\n.card-hover{position:absolute;inset:0;display:flex;align-items:flex-end;justify-content:center;gap:10px;\n  padding-bottom:14px;background:linear-gradient(0deg,rgba(0,0,0,.72),transparent 55%);\n  opacity:0;transition:opacity .2s}\n.card:hover .card-hover{opacity:1}\n.mini-btn{font-size:12px;font-weight:700;border-radius:20px;padding:8px 16px;border:1px solid rgba(255,255,255,.4);\n  background:rgba(10,10,14,.7);color:#fff}\n.mini-btn.solid{background:#fff;color:#0b0b0f;border-color:#fff}\n/* ---------- collection shelf ---------- */\n.shelf{padding:36px 4vw 12px;max-width:1280px;margin:0 auto}\n.shelf h2{font-size:22px;margin-bottom:6px}\n.shelf h2 .nlab{color:var(--brand)}\n.shelf .sub{color:var(--mut);font-size:14px;margin-bottom:22px}\n.grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(272px,1fr));gap:14px}\n\n/* ---------- detail page ---------- */\n.backbar{position:absolute;top:0;left:0;right:0;z-index:50;padding:18px 4vw;\n  background:linear-gradient(180deg,rgba(5,5,8,.9),transparent)}\n.back{display:inline-flex;align-items:center;gap:8px;font-size:15px;font-weight:600;color:#fff;\n  background:rgba(255,255,255,.08);border:1px solid rgba(255,255,255,.16);border-radius:20px;padding:8px 18px}\n.back:hover{background:rgba(255,255,255,.16)}\n.d-hero{position:relative;min-height:78vh;display:flex;align-items:flex-end;overflow:hidden}\n.d-shade{position:absolute;inset:0;background:linear-gradient(77deg,rgba(6,6,10,.95) 25%,rgba(6,6,10,.45) 55%,transparent 80%),\n  linear-gradient(0deg,var(--bg) 4%,transparent 34%),linear-gradient(180deg,rgba(6,6,10,.55),transparent 30%)}\n.d-body{position:relative;z-index:2;padding:0 4vw 8vh;max-width:900px}\n.d-title{font-family:var(--serif);font-size:clamp(44px,6vw,84px);font-weight:700;letter-spacing:-.5px;\n  line-height:1.02;margin:12px 0 18px}\n.d-meta{display:flex;flex-wrap:wrap;align-items:center;gap:10px;margin-bottom:16px;font-size:14px;color:#d7d7de}\n.d-meta .m{border:1px solid var(--line);background:rgba(255,255,255,.05);padding:5px 12px;border-radius:5px;font-size:12.5px}\n.d-meta .m b{color:var(--brand);font-weight:700}\n.d-log{font-size:clamp(16px,1.8vw,19px);line-height:1.6;color:#e2e2e9;max-width:62ch;margin-bottom:28px}\n.d-btns{display:flex;gap:12px;flex-wrap:wrap;margin-bottom:8px}\n.d-sec{padding:34px 4vw;max-width:1200px}\n.d-sec h2{font-size:22px;margin-bottom:6px}\n.d-sec .sub{color:var(--mut);font-size:14px;margin-bottom:20px}\n.ex-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(250px,1fr));gap:14px}\n.ex{background:var(--panel);border:1px solid var(--line);border-radius:10px;padding:20px;transition:border-color .2s,transform .2s}\n.ex:hover{border-color:#3a3a48;transform:translateY(-3px)}\n.ex .k{font-size:11px;font-weight:800;letter-spacing:2px;color:var(--brand);margin-bottom:10px}\n.ex h3{font-size:16px;margin-bottom:8px;line-height:1.35}\n.ex p{font-size:13.5px;color:var(--mut);line-height:1.55}\n.feat{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;list-style:none}\n.feat li{background:var(--bg2);border:1px solid var(--line);border-radius:8px;padding:14px 16px;font-size:13.5px;color:#d7d7de}\n.feat li::before{content:\"\u2713 \";color:var(--brand);font-weight:800}\n.like-row{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:12px}\n\n/* ---------- footer ---------- */\nfooter{margin-top:60px;padding:40px 4vw 60px;color:var(--dim);font-size:13px;border-top:1px solid #17171e}\nfooter .fbrand{font-family:var(--cond);letter-spacing:4px;color:var(--brand);font-weight:800;margin-bottom:14px}\nfooter p{max-width:70ch;line-height:1.7;margin-bottom:8px}\nfooter nav{display:flex;gap:22px;flex-wrap:wrap;margin-top:16px}\nfooter nav a{color:var(--mut)}\nfooter nav a:hover{color:#fff}\n\n/* ---------- responsive / motion ---------- */\n@media (max-width:760px){\n  .nav-links{display:none}\n  .billboard{height:88vh;min-height:560px}\n  .grid{grid-template-columns:repeat(auto-fill,minmax(200px,1fr))}\n  .card:hover{transform:translateY(-4px)}\n}\n@media (prefers-reduced-motion:reduce){\n  .slide{animation:none;opacity:0}\n  .slide:first-child{opacity:1}\n  *{transition:none!important}\n}\n";

function handle(req) {
  var url = new URL(req.url);
  var p = url.pathname;
  if (p === "/") return new Response(PAGES.home, { status: 200, headers: HEADERS_HTML });
  if (p === "/apps/style.css") return new Response(CSS, { status: 200, headers: HEADERS_CSS });
  var m = p.match(/^\/apps\/([a-z0-9-]+)\/?$/);
  if (m && PAGES[m[1]]) return new Response(PAGES[m[1]], { status: 200, headers: HEADERS_HTML });
  if (p === "/apps" || p === "/apps/") return Response.redirect(url.origin + "/", 302);
  return new Response("not found", { status: 404, headers: HEADERS_HTML });
}
